package net.battlespades;

import java.util.*;
import net.battlespades.ugc.*;
import net.battlespades.entities.*;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.world.*;
import net.battlespades.rules.GameRules;
import net.battlespades.support.LifeHarness;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class UgcEditorTest {
    private static final byte[] SOURCE={0,(byte)239,(byte)239,0,0,0,0,0};
    private static final class Harness implements AutoCloseable,UgcEditor.Ports,UgcEditor.Store {
        final MutableWorld world=new MutableWorld(VxlMap.load(SOURCE,"retail"),1,1024);final EntityRegistry entities=new EntityRegistry();final UgcProject project;final ArrayDeque<Runnable> worker=new ArrayDeque<>(),owner=new ArrayDeque<>();final List<GamePacket> sent=new ArrayList<>();final List<Throwable> errors=new ArrayList<>();final List<String> checkpoints=new ArrayList<>(),full=new ArrayList<>();final UgcEditor editor;boolean fail;
        Harness(String account){this(account,false);}
        Harness(String account,boolean pristine){var initial=new UgcProject("Old","","","grassland","ctf");project=pristine?UgcProject.parse(initial.json().replace("\"modified_since_publish\":true","\"modified_since_publish\":false"),"Old",null):initial;editor=new UgcEditor(project,world,SOURCE,entities,List.of("Construct"),account,owner::add,worker::add,this,this);}
        public void broadcast(GamePacket packet,Object exclude){sent.add(packet);}public void send(Object connection,GamePacket packet){sent.add(packet);}public void failure(Throwable error){errors.add(error);}
        public void checkpoint(String json)throws Exception{if(fail){fail=false;throw new java.io.IOException("Controlled write failure");}checkpoints.add(json);}public void save(UgcWorkspace.Snapshot snapshot){full.add(snapshot.sidecar());assertTrue(snapshot.vxl().length>0);}
        void pump(){for(int i=0;i<20&&(!worker.isEmpty()||!owner.isEmpty());i++){if(!worker.isEmpty())worker.removeFirst().run();if(!owner.isEmpty())owner.removeFirst().run();}assertTrue(worker.isEmpty()&&owner.isEmpty());}
        public void close(){var done=editor.deactivate();pump();done.toCompletableFuture().join();world.close();}
    }
    @Test void ownershipMarkersSelectionAndRemovalStayBoundToCurrentSocket(){try(var h=new Harness("")){Object host=new String("same"),guest=new String("same");h.editor.connected(host,"");h.editor.connected(guest,"");assertTrue(h.editor.isHost(host));assertFalse(h.editor.isHost(guest));assertFalse(h.editor.placeAuthorized(guest,10,10,10,7,true,0));assertTrue(h.editor.placeAuthorized(host,10,10,10,7,true,12));var entity=h.entities.all().getFirst();assertEquals(29,entity.type);assertEquals(2,entity.state);assertEquals(8,entity.ugcMode);assertEquals(List.of(7),entity.intProperties);var replay=new ArrayList<GamePacket>();h.editor.reveal(replay::add);assertEquals(List.of(98,68,21),replay.stream().map(GamePacket::id).toList());assertTrue(h.editor.placeAuthorized(host,11,10,10,0,false,13));var removed=h.sent.stream().filter(p->p instanceof SimplePackets.PlaceUGC v&&v.placing()==0).map(p->(SimplePackets.PlaceUGC)p).findFirst().orElseThrow();assertEquals(10,removed.x());assertEquals(7,removed.ugc_item_id());assertTrue(h.entities.all().isEmpty());var selection=h.editor.selection(new ClassCatalog.Selection(0,List.of(),List.of("construct","bad","bad","bad","bad"),List.of(0,1)));assertEquals(13,selection.classId());assertEquals(List.of("Construct"),selection.prefabs());assertTrue(selection.ugcTools().isEmpty());assertFalse(selection.loadout().contains(23));assertTrue(selection.loadout().contains(41)&&selection.loadout().contains(42));h.editor.left(host);assertFalse(h.editor.isHost(host));assertFalse(h.editor.isHost(guest));h.editor.connected(guest,"");assertTrue(h.editor.isHost(guest));}}
    @Test void liveHeldToolTopSupportAndDistanceGatePeerObjects(){try(var h=new Harness("verified");var life=new LifeHarness(GameRules.serverDefaults(),"ugc",h.world)){Object guest=new Object(),host=new Object();h.editor.connected(guest,"other");h.editor.connected(host,"verified");assertFalse(h.editor.isHost(guest));assertTrue(h.editor.isHost(host));life.runtime.admit(0,new SimplePackets.NewPlayerConnection(2,13,0,0,"Builder"),h.editor.selection(new ClassCatalog.Selection(13,List.of(),List.of(),List.of(7))),0);var player=life.runtime.players().iterator().next();player.fire().tool(41,true);player.body().position(new net.battlespades.physics.PlayerPhysics.Vector(255,255,235));var packet=new SimplePackets.PlaceUGC(9,255,255,238,7,1);assertTrue(h.editor.place(host,player,packet,20));assertFalse(h.editor.place(guest,player,packet,21));assertFalse(h.editor.place(host,player,new SimplePackets.PlaceUGC(10,254,255,237,7,1),21));assertFalse(h.editor.place(host,player,new SimplePackets.PlaceUGC(10,0,0,238,7,1),21));player.fire().tool(5,true);assertFalse(h.editor.place(host,player,new SimplePackets.PlaceUGC(11,255,255,238,7,0),22));h.editor.deactivate();h.pump();}}
    @Test void serializedCheckpointAndExplicitSaveSnapshotAfterOlderWrites(){try(var h=new Harness("")){Object host=new Object();h.editor.connected(host,"");assertTrue(h.editor.title(host,"Old checkpoint"));h.editor.tick(0);assertEquals(1,h.worker.size());h.editor.title(host,"New save");var save=h.editor.save(host);h.worker.removeFirst().run();h.owner.removeFirst().run();assertFalse(save.toCompletableFuture().isDone());assertEquals(1,h.worker.size());h.editor.title(host,"Edit while save runs");h.editor.checkpoint();h.editor.tick(1);h.editor.title(host,"Latest metadata");h.pump();assertTrue(save.toCompletableFuture().join());assertEquals("Old checkpoint",UgcProject.parse(h.checkpoints.getFirst(),"",null).title());assertEquals("New save",UgcProject.parse(h.full.getFirst(),"",null).title());assertEquals("Latest metadata",UgcProject.parse(h.checkpoints.getLast(),"",null).title());assertTrue(h.errors.isEmpty());}}
    @Test void failedCheckpointRetriesAndFinalFlushWaitsForPendingSave(){try(var h=new Harness("",true)){assertFalse(h.project.modified());h.world.set(new MutableWorld.Cell(255,255,239),true,0x123456,null);Object host=new Object();h.editor.connected(host,"");h.fail=true;h.editor.checkpoint();h.editor.tick(0);assertTrue(h.project.modified());h.pump();assertEquals(1,h.errors.size());h.editor.tick(1);h.pump();assertEquals(1,h.checkpoints.size());var save=h.editor.save(host);h.editor.title(host,"Final change");var stop=h.editor.deactivate();assertFalse(stop.toCompletableFuture().isDone());h.pump();assertTrue(save.toCompletableFuture().join());stop.toCompletableFuture().join();assertEquals("Final change",UgcProject.parse(h.full.getLast(),"",null).title());assertTrue(h.entities.all().isEmpty());}}
}
